with detail = 1 {
    with link = "line.dk.ABH" {
        track(:first :pax :removed, path("d1.dk.abh")[:gug.yh, :han]);
    }

    with link = "line.dk.AHG" {
        let ag = path("d1.dk.ahg");

        with railway = :first :cat:dc75 :pax {
            track(:double, ag[:aar, :ost]);
            track(ag[:ost, :ryo.yr]);
            track(ag[:ryo.yr, :ryo.yh]);
            track(ag[:ryo.yh, :tru.ye]);
            track(ag[:tru.ye, :gre]);
        }
    }

    with link = "line.dk.AHS" {
        let sh = path("d1.dk.ahs");

        with railway = :first :pax :removed {
            track(sh[:sve.yh, :aar.ys]);
            track(sh[:aar.yh, :hva]);
        }
    }

    with link = "line.dk.AHT" {
        let at = path("d1.dk.aht.1");

        with railway = :first :pax :removed {
            track(at[:aar.yt, :ham.yt]);
            track(at[:ham.yt, :ham]);
            track(path("d1.dk.aht.2")[:ham.yt, :tho.ya]);
        }
    }

    with link = "line.dk.AOH" {
        let ao = path("d1.dk.aoh");

        with railway = :first :museum {
            track(ao[:aal.yh, :gug.yh]);
            track(ao[:gug.yh, :oha]);
        }
    }
}

